<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch,nextTick} from 'vue';
import {vModal} from './modal';
import {validCloudDirectory} from './cloud-files-route';
import type {CleanupCandidate,CleanupEntry} from './cleanup-types';
import {batchID,validBatch,freezeCleanupRequest,cleanupStatus,createCleanupBatchID,cleanupEventLabel,cleanupReasonLabel} from './cleanup-batch';
import type {CleanupBatchRecord} from './cleanup-batch';
const props=defineProps<{candidates:CleanupCandidate[];disabled:boolean;reconcile:()=>Promise<boolean>}>(),emit=defineEmits<{locked:[boolean];authenticationRequired:[]}>();
const fixed=ref<CleanupCandidate[]|null>(null),ack=ref(false),pending=ref(false),minimized=ref(false),consumed=ref(false),ambiguous=ref(false),message=ref(''),shown=ref(50);
const selectedID=ref(''),record=ref<CleanupBatchRecord|null>(null),items=ref<any[]>([]),history=ref<CleanupBatchRecord[]>([]),events=ref<any[]>([]),eventAfter=ref('0'),eventMore=ref(false),historyLoaded=ref(false),historyLoading=ref(false),historyError=ref(''),readError=ref(''),observed=ref(''),browserObserved=ref(''),historyOffset=ref(0),historyTotal=ref(0),offset=ref(0),reading=ref(false),stopping=ref(false);
let active=true,generation=0,timer:ReturnType<typeof setTimeout>|undefined,frozenWire='',lastConfirmed=0,historyRequest=0,eventRequest=0;
const exact=(x:unknown)=>typeof x==='string'&&/^(0|[1-9][0-9]*)$/.test(x)&&x.length<=19&&BigInt(x)<=9223372036854775807n;
const validEntry=(e:CleanupEntry)=>e&&exact(e.fs_id)&&e.fs_id!=='0'&&exact(e.size)&&exact(e.provider_mtime)&&typeof e.path==='string'&&validCloudDirectory(e.path)&&e.path!=='/'&&typeof e.name==='string';
function prepare(){
 if(!active||props.disabled||pending.value||ambiguous.value||!props.candidates.length||props.candidates.length>1000)return;
 const ids=new Set<string>(),paths=new Set<string>();
 for(const item of props.candidates){if(!validEntry(item.entry)||ids.has(item.entry.fs_id)||paths.has(item.entry.path)||(item.kind==='empty'?item.entry.directory!==true:item.kind!=='duplicate'||item.entry.directory!==false||!item.retained||!validEntry(item.retained)||item.retained.directory!==false||item.retained.fs_id===item.entry.fs_id||item.retained.size!==item.entry.size||!item.sha256||!/^[a-f0-9]{64}$/.test(item.sha256))){message.value='选择包含无效或重复身份，请刷新预览后重新选择。';return;}ids.add(item.entry.fs_id);paths.add(item.entry.path);}
 if(props.candidates.some(item=>item.retained&&(ids.has(item.retained.fs_id)||paths.has(item.retained.path)))){message.value='保留副本同时出现在待删清单中，请重新选择。';return;}
 fixed.value=JSON.parse(JSON.stringify(props.candidates));ack.value=false;minimized.value=false;consumed.value=false;shown.value=50;message.value='';emit('locked',true);
}

function close(){if(!pending.value){fixed.value=null;emit('locked',false);}}
function login(){generation++;clearTimeout(timer);record.value=null;observed.value='';browserObserved.value='';items.value=[];events.value=[];history.value=[];historyLoaded.value=false;historyTotal.value=0;historyOffset.value=0;historyLoading.value=false;emit('authenticationRequired');}
function select(id:string){if(!batchID(id)||!active||props.disabled||(ambiguous.value&&selectedID.value&&selectedID.value!==id))return;clearTimeout(timer);generation++;reading.value=false;historyLoading.value=false;readError.value='';message.value='';selectedID.value=id;record.value=null;observed.value='';browserObserved.value='';items.value=[];events.value=[];eventAfter.value='0';eventMore.value=false;offset.value=0;lastConfirmed=0;const url=new URL(location.href);url.searchParams.set('batch_id',id);window.history.replaceState(null,'',url);void loadBatch();}
async function loadHistory(at=historyOffset.value){
 if(!active||props.disabled||!Number.isSafeInteger(at)||at<0)return;
 const run=generation,request=++historyRequest;historyLoading.value=true;
 try{const response=await fetch('/api/cloud/cleanup-batches?offset='+at+'&limit=25',{credentials:'same-origin'});
 if(!active||run!==generation||request!==historyRequest)return;if(response.status===401){login();return;}
 const data=await response.json();if(!active||run!==generation||request!==historyRequest)return;
 if(!response.ok||!Array.isArray(data.batches)||data.batches.length>25||!Number.isSafeInteger(data.total)||data.total<0||data.offset!==at||data.limit!==25||data.batches.length!==Math.min(25,Math.max(0,data.total-at))||data.batches.some((b:any)=>!validBatch(b,b.batch_id))||new Set(data.batches.map((b:any)=>b.batch_id)).size!==data.batches.length)throw Error();
 history.value=data.batches;historyOffset.value=at;historyTotal.value=data.total;historyLoaded.value=true;historyError.value='';
 }catch{if(active&&run===generation&&request===historyRequest)historyError.value='批次历史读取失败，可手动重试。';}finally{if(active&&run===generation&&request===historyRequest)historyLoading.value=false;}
}
async function loadBatch(page=offset.value){
 if(!active||props.disabled||!batchID(selectedID.value)||reading.value||!Number.isSafeInteger(page)||page<0)return;clearTimeout(timer);reading.value=true;const run=generation,id=selectedID.value;
 try{const responses=await Promise.all([fetch('/api/cloud/cleanup-batches/'+id,{credentials:'same-origin'}),fetch('/api/cloud/cleanup-batches/'+id+'/items?offset='+page+'&limit=25',{credentials:'same-origin'})]);if(!active||run!==generation||id!==selectedID.value)return;if(responses.some(r=>r.status===401)){login();return;}if(responses.some(r=>!r.ok))throw Error();const [batch,detail]=await Promise.all(responses.map(r=>r.json()));if(!active||run!==generation||id!==selectedID.value)return;
 if(typeof detail.observed_at_utc!=='string'||!detail.observed_at_utc.endsWith('Z')||!Number.isFinite(Date.parse(detail.observed_at_utc))||!validBatch(batch,id)||detail.total!==batch.item_count||!Array.isArray(detail.items)||detail.items.some((i:any)=>!validEntry(i.expected)||!Number.isSafeInteger(i.ordinal)||i.ordinal<page||i.ordinal>=Math.min(page+25,batch.item_count)||!['pending','sending','confirmed','failed','unknown'].includes(i.status)))throw Error();
 if(ambiguous.value)message.value='已按原批次 ID 读取到后台记录；当前状态以下方观察为准。';record.value=batch;offset.value=page;items.value=detail.items;observed.value=detail.observed_at_utc||'';browserObserved.value=new Date().toISOString();readError.value='';ambiguous.value=false;
 if(batch.confirmed>lastConfirmed){lastConfirmed=batch.confirmed;void props.reconcile().catch(()=>false);}
 if(['queued','running'].includes(batch.status))timer=setTimeout(()=>{void loadBatch();},2000);return true;
 }catch{if(active&&run===generation&&id===selectedID.value)readError.value='批次状态暂时无法读取，保留上次观察；这不代表执行已停止。请按原批次 ID 刷新核对。';}finally{if(run===generation)reading.value=false;}
}
async function submit(retry=false){
 if(!active||props.disabled||pending.value||(!retry&&(!fixed.value||!ack.value||consumed.value)))return;
 if(!retry){generation++;clearTimeout(timer);reading.value=false;readError.value='';record.value=null;observed.value='';browserObserved.value='';items.value=[];events.value=[];offset.value=0;lastConfirmed=0;selectedID.value=createCleanupBatchID();frozenWire=freezeCleanupRequest(selectedID.value,fixed.value!);consumed.value=true;const url=new URL(location.href);url.searchParams.set('batch_id',selectedID.value);window.history.replaceState(null,'',url);}
 if(!frozenWire)return;pending.value=true;emit('locked',true);const run=generation,id=selectedID.value;
 try{const response=await fetch('/api/cloud/cleanup-batches',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:frozenWire});if(!active||run!==generation)return;if(response.status===401){login();return;}if(response.status===400){ambiguous.value=false;message.value='清理清单被拒绝，尚未创建批次；请刷新候选重新核对。';return;}if(!response.ok)throw Error();const data=await response.json();if(!active||run!==generation)return;if(data.batch_id!==id)throw Error();message.value='清理批次已保存到后台，离开页面仍会继续。';ambiguous.value=false;
 }catch{if(active&&run===generation){ambiguous.value=true;message.value='提交结果尚未确认，请按原批次 ID 查询；不会自动重发或新建批次。';}}
 finally{if(run===generation){pending.value=false;minimized.value=true;emit('locked',false);void loadBatch();void loadHistory(0);}}
}
async function stop(){if(!active||props.disabled||stopping.value||!record.value||!['queued','running'].includes(record.value.status))return;const run=generation,id=selectedID.value;stopping.value=true;
 try{const response=await fetch('/api/cloud/cleanup-batches/'+id+'/stop',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'});if(!active||run!==generation)return;if(response.status===401){login();return;}if(!response.ok)throw Error();message.value='停止请求已处理；已发送项目仍按实际回执记录。';void loadBatch();}catch{if(active&&run===generation)message.value='停止请求未能确认，请刷新批次状态；不要假定已停止。';}finally{if(run===generation)stopping.value=false;}}
async function loadEvents(after='0'){const run=generation,request=++eventRequest,id=selectedID.value;try{const response=await fetch('/api/cloud/cleanup-batches/'+id+'/events?after_sequence='+after+'&limit=100',{credentials:'same-origin'});if(!active||run!==generation||request!==eventRequest||id!==selectedID.value)return;if(response.status===401){login();return;}const data=await response.json();if(!active||run!==generation||request!==eventRequest||id!==selectedID.value)return;if(!response.ok||!Array.isArray(data.events)||data.events.length>100||typeof data.next_sequence!=='string'||!exact(data.next_sequence)||typeof data.has_more!=='boolean'||data.events.some((e:any)=>!exact(e.sequence)||BigInt(e.sequence)<=BigInt(after)))throw Error();events.value=data.events;eventAfter.value=data.next_sequence;eventMore.value=data.has_more;}catch{if(active&&run===generation&&request===eventRequest)readError.value='事件读取失败，请重试。';}}
async function locateItem(ordinal:number){
 if(reading.value||!record.value||!Number.isSafeInteger(ordinal)||ordinal<0||ordinal>=record.value.item_count)return;
 const run=generation,id=selectedID.value,page=Math.floor(ordinal/25)*25;
 const published=await loadBatch(page);await nextTick();
 if(!published||!active||props.disabled||run!==generation||id!==selectedID.value||offset.value!==page)return;
 document.querySelector<HTMLElement>('[data-cleanup-ordinal="'+ordinal+'"]')?.focus();
}
function hide(){if(pending.value&&frozenWire){ambiguous.value=true;message.value='页面已停止观察，请按原批次 ID 核对；后台可能仍在执行。';}active=false;generation++;clearTimeout(timer);reading.value=false;historyLoading.value=false;pending.value=false;stopping.value=false;minimized.value=true;emit('locked',false);}
function restore(event:PageTransitionEvent){if(event.persisted&&!props.disabled){active=true;void loadBatch();void loadHistory();}}
watch(()=>props.disabled,value=>{if(value){hide();record.value=null;observed.value='';browserObserved.value='';items.value=[];events.value=[];history.value=[];historyLoaded.value=false;historyTotal.value=0;historyOffset.value=0;}});
onMounted(()=>{const id=new URL(location.href).searchParams.get('batch_id');if(batchID(id)){ambiguous.value=true;select(id);}void loadHistory();window.addEventListener('pagehide',hide);window.addEventListener('pageshow',restore);});
onUnmounted(()=>{hide();window.removeEventListener('pagehide',hide);window.removeEventListener('pageshow',restore);});
</script>
<template><section class="event-results"><header class="page-header"><h2>执行所选清理</h2><button class="button primary" data-testid="cleanup-prepare" :disabled="disabled||pending||ambiguous||!candidates.length||candidates.length>1000" @click="prepare">核对并清理 {{candidates.length}} 项</button></header><p class="muted">固定清单保存到后台后逐项核对与执行，离页不会停止。重复文件重新读取待删及保留副本计算哈希；每批最多 1000 项。</p>
<p v-if="message" class="notice" role="status">{{message}}</p><button v-if="ambiguous&&frozenWire" class="button secondary" :disabled="disabled||pending" @click="submit(true)">按原 ID 重新提交同一清单</button>
<section v-if="selectedID" data-testid="cleanup-progress"><header class="page-header"><h3>后台清理批次</h3><button class="button secondary" :disabled="disabled||reading" @click="loadBatch()">刷新批次</button></header><p class="muted">批次 {{selectedID}}</p><p class="muted" data-testid="cleanup-read-evidence">浏览器读取 UTC：<time data-read-source="browser">{{browserObserved||'尚未读取'}}</time> · 服务端读取 UTC：<time data-read-source="server">{{observed||'尚无观察'}}</time></p><p v-if="readError" class="notice danger" role="alert">{{readError}}</p><template v-if="record"><p role="status">{{cleanupStatus(record.status)}} · 已确认 {{record.confirmed}} / {{record.item_count}} · 未执行 {{record.pending}} · 发送中 {{record.sending}} · 失败 {{record.failed}} · 未知 {{record.unknown}}</p><p v-if="record.status==='unknown'" class="notice danger">结果未知，后续项目已停止。保持隔离，不能直接重发删除。</p><button v-if="['queued','running'].includes(record.status)" class="button secondary" data-testid="cleanup-stop" :disabled="disabled||stopping||record.stop_requested" @click="stop">{{record.stop_requested?'已请求停止后续项目':'停止后续项目'}}</button><div class="event-table-scroll"><table><thead><tr><th>网盘路径</th><th>状态</th><th>保留副本</th><th>证据</th></tr></thead><tbody><tr v-for="item in items" :key="item.ordinal" :data-cleanup-ordinal="item.ordinal" tabindex="-1"><td>{{item.expected.path}}</td><td>{{cleanupStatus(item.status)}}</td><td>{{item.retained?.path||'—'}}</td><td><a v-if="item.operation_id" :href="'/operations?operation_id='+item.operation_id">操作记录</a><span v-else>尚无发送记录</span></td></tr></tbody></table></div><button class="button secondary" :disabled="disabled||reading||offset===0" @click="loadBatch(offset-25)">上一页</button><span data-testid="cleanup-items-page"> 第 {{Math.floor(offset/25)+1}} 页 </span><button class="button secondary" :disabled="disabled||reading||offset+25>=record.item_count" @click="loadBatch(offset+25)">下一页</button><button class="button secondary" :disabled="disabled" @click="loadEvents('0')">查看批次事件</button><button v-if="eventMore" class="button secondary" :disabled="disabled" @click="loadEvents(eventAfter)">下一批事件</button><div v-if="events.length" class="event-table-scroll"><table><thead><tr><th>事件 / 项目</th><th>服务端记录 UTC</th><th>远端响应 UTC</th><th>原因</th></tr></thead><tbody><tr v-for="event in events" :key="event.sequence"><td><span :title="event.kind">{{cleanupEventLabel(event.kind)}}</span><button v-if="Number.isSafeInteger(event.ordinal)" class="button secondary compact" :disabled="disabled||reading" @click="locateItem(event.ordinal)">查看项目 {{event.ordinal+1}}</button><a v-if="batchID(event.operation_id)" :href="'/operations?operation_id='+event.operation_id">操作记录</a></td><td>{{event.recorded_at_utc}}</td><td>{{event.response_observed_at_utc||'—'}}</td><td :title="event.reason">{{cleanupReasonLabel(event.reason)}}</td></tr></tbody></table></div></template></section>
<header class="page-header"><h3>清理批次历史</h3><button class="button secondary" data-testid="cleanup-history-refresh" :disabled="disabled||historyLoading" @click="loadHistory()">刷新历史</button></header><p v-if="historyLoading&&!historyLoaded" role="status">正在读取批次历史…</p><p v-if="historyError" class="notice">{{historyError}}<span v-if="historyLoaded"> · 下方保留上次读取结果。</span></p><div class="event-table-scroll"><table><thead><tr><th>服务端首次接收 UTC</th><th>状态</th><th>已确认 / 总项</th><th>操作</th></tr></thead><tbody><tr v-for="batch in history" :key="batch.batch_id"><td>{{batch.created_at_utc}}</td><td>{{cleanupStatus(batch.status)}}</td><td>{{batch.confirmed}} / {{batch.item_count}}</td><td><button class="button secondary" :disabled="disabled||pending||ambiguous" @click="select(batch.batch_id)">查看批次</button></td></tr><tr v-if="historyLoaded&&!history.length&&!historyError"><td colspan="4">暂无已读取的清理批次。</td></tr></tbody></table></div>
<p v-if="historyLoaded" data-testid="cleanup-history-page">第 {{Math.floor(historyOffset/25)+1}} 页 · 共 {{historyTotal}} 批</p><button class="button secondary" :disabled="disabled||historyLoading||historyOffset===0" @click="loadHistory(historyOffset-25)">上一页历史</button><button class="button secondary" data-testid="cleanup-history-next" :disabled="disabled||historyLoading||historyOffset+25>=historyTotal" @click="loadHistory(historyOffset+25)">下一页历史</button>
<div v-if="fixed" v-show="!minimized" class="modal-backdrop"><section class="detail-drawer" role="dialog" aria-modal="true" aria-labelledby="cleanup-batch-title" v-modal="close"><header class="page-header"><h2 id="cleanup-batch-title">确认删除网盘 {{fixed.length}} 项</h2><button class="button secondary" :disabled="pending" @click="close">关闭</button></header><p class="notice danger">清单固定后交给后台逐项核对；失败或未知会停止同批后续。已发送请求不能撤销，离页不会停止后台执行。</p><div class="event-table-scroll"><table><thead><tr><th>待删除路径</th><th>类型</th><th>保留副本</th></tr></thead><tbody><tr v-for="item in fixed.slice(0,shown)" :key="item.entry.fs_id"><td>{{item.entry.path}}</td><td>{{item.kind==='empty'?'空目录':'重复文件'}}</td><td>{{item.retained?.path||'—'}}</td></tr></tbody></table></div><button v-if="shown<fixed.length" class="button secondary" @click="shown+=50">再显示 50 项</button><label><input type="checkbox" data-testid="cleanup-batch-ack" v-model="ack" :disabled="pending||consumed"/>我已核对删除范围、保留副本与带宽影响</label><button class="button primary" data-testid="cleanup-batch-confirm" :disabled="disabled||pending||consumed||!ack" @click="submit(false)">{{pending?'正在保存批次…':consumed?'本清单已提交':'确认执行清理'}}</button></section></div></section></template>
<style scoped>.detail-drawer table{min-width:0;width:100%;table-layout:fixed}.detail-drawer th,.detail-drawer td{white-space:normal;overflow-wrap:anywhere}.detail-drawer>label{display:block;margin:16px 0 12px}.detail-drawer>button{margin:0 8px 8px 0}td{overflow-wrap:anywhere}tr:focus{outline:2px solid #476fe8;outline-offset:-2px}</style>
